/* Opt-in per-exec diagnostics. No guest arguments, environment values, paths
 * or output are logged. Timers overlap; totals are not a CPU partition. */
#include "cng/profile.h"
#include "cng/image_cache.h"
#include "cng/loader_probe.h"
#include "cng/rewrite.h"
#include "cng/broker.h"
#include "cng/monitor.h"
#include "cng/rt.h"
#include "cng/syscall.h"
#include "cng/uapi.h"

#define PROFILE_NRS 512
#define PROFILE_PREFIX "TRITONTERM_CNG_PROFILE "
int cng_profile_support;
static int mode, installed, reported, initial_scope;
static unsigned generation;
static long owner_pid, startup_tid;
static unsigned long started, entered;
static long cpu_start[18];
static int cpu_ok;
static char program[64];
static unsigned long calls[CNG_P_METRICS], nanos[CNG_P_METRICS];
static unsigned long syscalls[PROFILE_NRS], tiers[3];
static const char *names[CNG_P_METRICS] = {
    "resolve", "pin", "metadata", "elf_headers", "elf_map", "rewrite",
    "library_map", "dispatch", "file_maps", "anonymous_maps", "copied_bytes",
    "rewrite_bytes", "rewrite_sites", "metadata_opens", "metadata_hits", "path_probes",
    "loader_anonymous_objects", "loader_file_objects", "stack", "close_cloexec",
    "exec_sweep", "exec_reset", "exec_reap", "loader_fill",
    "loader_protect", "loader_sync", "loader_sync_bytes", "image_hits",
    "image_misses", "image_fallbacks", "image_objects", "image_patch_bytes", "image_fetch",
    "statx_absolute", "statx_cwd", "statx_dirfd", "statx_empty",
    "statx_reuse_abs", "statx_reuse_resolved", "statx_fallback",
    "metadata_open_ok", "metadata_absent", "metadata_open_error",
    "metadata_parsed", "metadata_collision", "metadata_admission",
    "copy_pvm", "copy_memfd", "statx_reuse_error"
};

static unsigned long now(void) {
    struct cng_timespec ts;
    if (sys_clock_gettime(CNG_CLOCK_MONOTONIC, &ts) < 0)
        return 0;
    return (unsigned long)ts.tv_sec * 1000000000UL + ts.tv_nsec;
}
static int enabled(void) {
    if (!__atomic_load_n(&mode, __ATOMIC_RELAXED))
        return 0;
    long tid = __atomic_load_n(&startup_tid, __ATOMIC_RELAXED);
    return !tid || tid == sys_gettid();
}
void cng_profile_init(void) {
    const char *value = cng_broker_env("CNG_PROFILE_SUPPORT");
    cng_profile_support = value && !strcmp(value, "1");
}
void cng_profile_monitor(int value) { installed = value; }
struct cng_profile_span cng_profile_begin(unsigned metric) {
    struct cng_profile_span span = {0, 0};
    if (metric >= CNG_P_METRICS || !enabled())
        return span;
    span.generation = __atomic_load_n(&generation, __ATOMIC_RELAXED);
    __atomic_fetch_add(&calls[metric], 1, __ATOMIC_RELAXED);
    if (__atomic_load_n(&mode, __ATOMIC_RELAXED) == 2)
        span.start = now();
    return span;
}
void cng_profile_end(unsigned metric, struct cng_profile_span span) {
    if (!span.start || metric >= CNG_P_METRICS || !enabled() ||
        span.generation != __atomic_load_n(&generation, __ATOMIC_RELAXED))
        return;
    unsigned long end = now();
    if (end >= span.start)
        __atomic_fetch_add(&nanos[metric], end - span.start, __ATOMIC_RELAXED);
}
void cng_profile_add(unsigned metric, unsigned long amount) {
    if (metric < CNG_P_METRICS && enabled())
        __atomic_fetch_add(&calls[metric], amount, __ATOMIC_RELAXED);
}
void cng_profile_syscall(long nr, int trapped) {
    if (!enabled())
        return;
    if (nr >= 0 && nr < PROFILE_NRS)
        __atomic_fetch_add(&syscalls[nr], 1, __ATOMIC_RELAXED);
    unsigned tier = trapped == CNG_DISP_HANDLER ? 1 : trapped == CNG_DISP_BOUNCED ? 2 : 0;
    __atomic_fetch_add(&tiers[tier], 1, __ATOMIC_RELAXED);
}
static unsigned long cpu_ns(const long *usage, int index) {
    return (unsigned long)usage[index] * 1000000000UL + usage[index + 1] * 1000UL;
}
static void report_write(const char *output, size_t length) {
    /* Diagnostics must not turn a successful command into SIGPIPE when a
     * stderr reader goes away. Preserve the guest's mask and any SIGPIPE
     * already pending; consume only a new signal generated by our write. */
    unsigned long bit = 1UL << (13 - 1), saved, pending;
    if (CNG_SYS(__NR_rt_sigprocmask, 0 /*BLOCK*/, &bit, &saved, 8, 0, 0) < 0)
        return;
    if (CNG_SYS(__NR_rt_sigpending, &pending, 8, 0, 0, 0, 0) == 0) {
        long result = cng_write_all(2, output, length);
        if (result == -EPIPE && !(pending & bit)) {
            struct cng_timespec zero = {0, 0};
            CNG_SYS(__NR_rt_sigtimedwait, &bit, 0, &zero, 8, 0, 0);
        }
    }
    CNG_SYS(__NR_rt_sigprocmask, 2 /*SETMASK*/, &saved, 0, 8, 0, 0);
}

static void report(const char *reason, long status) {
    int active = __atomic_load_n(&mode, __ATOMIC_RELAXED);
    if (!active || owner_pid != sys_getpid() ||
        __atomic_exchange_n(&reported, 1, __ATOMIC_RELAXED))
        return;
    unsigned long end = now();
    long usage[18];
    int have_cpu = cpu_ok && CNG_SYS(__NR_getrusage, 0, usage, 0, 0, 0, 0) == 0;
    unsigned long user = have_cpu ? cpu_ns(usage, 0) - cpu_ns(cpu_start, 0) : 0;
    unsigned long system = have_cpu ? cpu_ns(usage, 2) - cpu_ns(cpu_start, 2) : 0;
    /* Emit after taking time/CPU snapshots. Formatting and stderr I/O are
     * excluded from wall_ns, but included in the helper's external duration. */
    unsigned long ctr;
    __asm__ volatile("mrs %0, ctr_el0" : "=r"(ctr));
    int image_blocked; long image_stage, image_error;
    cng_image_cache_diagnostic(&image_blocked, &image_stage, &image_error);
    /* Keep every metric even at maximum counter width; the syscall histogram
     * alone may be truncated, and is always closed as valid JSON below. */
    char output[8192];
    size_t used = cng_snprintf(output, sizeof output,
        PROFILE_PREFIX "{\"v\":1,\"program\":\"%s\",\"pid\":%ld,\"mode\":\"%s\","
        "\"reason\":\"%s\",\"status\":%ld,\"wall_ns\":%lu,\"to_entry_ns\":%lu,"
        "\"initial_scope\":%d,\"cpu_available\":%d,\"user_ns\":%lu,\"system_ns\":%lu,"
        "\"seccomp\":%d,\"rewrite\":%d,\"cache\":{\"ctr_el0\":%lu,\"idc\":%lu,\"dic\":%lu,"
        "\"dline\":%lu,\"iline\":%lu},"
        "\"image_cache\":{\"enabled\":%d,\"blocked\":%d,\"stage\":%ld,\"error\":%ld},"
        "\"tiers\":[%lu,%lu,%lu],\"metrics\":{",
        program, owner_pid, active == 2 ? "timing" : "count", reason, status,
        end >= started ? end - started : 0, entered >= started ? entered - started : 0,
        initial_scope, have_cpu, user, system, installed, cng_g_rewrite,
        ctr, (ctr >> 28) & 1, (ctr >> 29) & 1,
        4UL << ((ctr >> 16) & 15), 4UL << (ctr & 15),
        cng_image_cache_enabled(), image_blocked, image_stage, image_error,
        __atomic_load_n(&tiers[0], __ATOMIC_RELAXED),
        __atomic_load_n(&tiers[1], __ATOMIC_RELAXED),
        __atomic_load_n(&tiers[2], __ATOMIC_RELAXED));
    for (unsigned i = 0; i < CNG_P_METRICS && used < sizeof output; i++)
        used += cng_snprintf(output + used, sizeof output - used,
            "%s\"%s\":[%lu,%lu]", i ? "," : "", names[i],
            __atomic_load_n(&calls[i], __ATOMIC_RELAXED),
            __atomic_load_n(&nanos[i], __ATOMIC_RELAXED));
    if (used >= sizeof output)
        return;
    used += cng_snprintf(output + used, sizeof output - used, "},\"syscalls\":{");
    int first = 1, truncated = 0;
    for (unsigned i = 0; i < PROFILE_NRS; i++) {
        unsigned long n = __atomic_load_n(&syscalls[i], __ATOMIC_RELAXED);
        if (!n)
            continue;
        if (used + 64 >= sizeof output) { truncated = 1; break; }
        used += cng_snprintf(output + used, sizeof output - used,
                             "%s\"%u\":%lu", first ? "" : ",", i, n);
        first = 0;
    }
    if (used + 40 >= sizeof output)
        return;
    used += cng_snprintf(output + used, sizeof output - used,
                         "},\"truncated\":%d}\n", truncated);
    report_write(output, used);
}
void cng_profile_exec(const char *path, char *const *envp, int initial) {
    if (!cng_profile_support)
        return;
    report("next_exec", 0);
    __atomic_store_n(&mode, 0, __ATOMIC_RELEASE);
    __atomic_add_fetch(&generation, 1, __ATOMIC_RELAXED);
    int requested = 0;
    const char key[] = "TRITONTERM_CNG_PROFILE=";
    for (char *const *p = envp; p && *p; p++) {
        if (strncmp(*p, key, sizeof key - 1))
            continue;
        const char *v = *p + sizeof key - 1;
        requested = !strcmp(v, "count") ? 1 : !strcmp(v, "timing") ? 2 : 0;
        break;
    }
    /* Explicit probe runs before measured snapshots, never on ordinary exec.
     * The collector invokes it in a separate command before timed workloads. */
    for (char *const *p = envp; p && *p; p++) {
        if (strcmp(*p, "TRITONTERM_CNG_LOADER_PROBE=1")) continue;
        static const char *strategies[CNG_LP_STRATEGIES] = {
            "private_patch", "direct_rx", "read_rx", "hybrid"
        };
        for (int i = 0; i < CNG_LP_STRATEGIES; i++) {
            struct cng_loader_probe_result r = cng_loader_probe(i);
            char output[256];
            size_t length = cng_snprintf(output, sizeof output,
                "TRITONTERM_CNG_LOADER_PROBE {\"v\":2,\"strategy\":\"%s\","
                "\"stage\":%ld,\"error\":%ld,\"signal\":%ld}\n",
                strategies[i], r.stage, r.error, r.signal);
            report_write(output, length);
        }
        break;
    }
    if (!requested)
        return;
    /* All timing work starts after the caller's validated argument snapshot.
     * Only the exec-planning thread contributes before the new image enters.
     * In-flight spans carry a generation and cannot time a successor image. */
    for (unsigned i = 0; i < CNG_P_METRICS; i++) {
        __atomic_store_n(&calls[i], 0, __ATOMIC_RELAXED);
        __atomic_store_n(&nanos[i], 0, __ATOMIC_RELAXED);
    }
    for (unsigned i = 0; i < PROFILE_NRS; i++)
        __atomic_store_n(&syscalls[i], 0, __ATOMIC_RELAXED);
    for (unsigned i = 0; i < 3; i++)
        __atomic_store_n(&tiers[i], 0, __ATOMIC_RELAXED);
    const char *base = strrchr(path, '/');
    base = base ? base + 1 : path;
    unsigned i;
    for (i = 0; base[i] && i + 1 < sizeof program; i++) {
        char c = base[i];
        program[i] = ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
                      (c >= '0' && c <= '9') || c == '.' || c == '-' || c == '_') ? c : '_';
    }
    program[i] = 0;
    owner_pid = sys_getpid();
    __atomic_store_n(&startup_tid, sys_gettid(), __ATOMIC_RELAXED);
    __atomic_store_n(&reported, 0, __ATOMIC_RELAXED);
    entered = 0;
    cpu_ok = CNG_SYS(__NR_getrusage, 0, cpu_start, 0, 0, 0, 0) == 0;
    started = now();
    initial_scope = initial;
    __atomic_store_n(&mode, requested, __ATOMIC_RELEASE);
}
void cng_profile_commit_thread(void) {
    if (__atomic_load_n(&mode, __ATOMIC_RELAXED))
        __atomic_store_n(&startup_tid, sys_gettid(), __ATOMIC_RELAXED);
}
void cng_profile_entry(void) {
    if (__atomic_load_n(&mode, __ATOMIC_RELAXED)) {
        entered = now();
        __atomic_store_n(&startup_tid, 0, __ATOMIC_RELAXED);
    }
}
void cng_profile_failure(long error) {
    report("exec_failed", error);
    __atomic_store_n(&mode, 0, __ATOMIC_RELEASE);
}
void cng_profile_exit(int status) { report("exit", status); }
